import sys,copy,json,itertools
sys.path[:0]=['/workspace/submission','/workspace/deps']
from campaign import audit
from common import Invalid,CaptureError,parse_json
job=json.load(open('/workspace/examples/fixtures.json'))[1]['input']

def run(j):
 try:return audit(j)
 except CaptureError:return {'error':'capture'}
 except (Invalid,ValueError,TypeError,KeyError,RecursionError):return {'error':'invalid'}

badvals=[None,True,False,0,1,1.,'',[],{},'x',['a'],{'a':2}]
errors=[]
for key in job:
 for value in badvals:
  j=copy.deepcopy(job);j[key]=value
  try:r=run(j)
  except BaseException as e:errors.append((key,value,type(e).__name__))
for arr in ['leases','services','requests','offers','request_quotas','offer_quotas','captures']:
 for key in job[arr][0]:
  for value in badvals:
   j=copy.deepcopy(job);j[arr][0][key]=value
   try:r=run(j)
   except BaseException as e:errors.append((arr,key,value,type(e).__name__))
print('uncaught failures',errors)
assert not errors
for text in ['\ufeff{}','{}{}','NaN','Infinity','-Infinity','{"x":1e999}','{"x":1,"x":2}', '{"x":0,"z":{"y":1,"y":2}}']:
 try:parse_json(text.encode())
 except Invalid:pass
 else:raise AssertionError(text)
# metadata invalid trumps every capture error
for c in [None,17*[{'encoding':'csv','chunks':[]}],[{'encoding':'bad','chunks':[]}],[{'encoding':'csv','chunks':['%']}]]:
 j=copy.deepcopy(job);j['captures']=c;j['seed']='bad name';assert run(j)=={'error':'invalid'}
 j['seed']='demo';assert run(j)=={'error':'capture'}
print('metadata tests passed')
PY
python3 -I -B /workspace/test_metadata.py
